    title: '제17조/제27조 (욕실 및 위생기구)',
    content: `[하자 판정 기준]\n1. 위생기구(세면대, 변기 등)의 파손, 균열, 고정 불량, 누수는 하자입니다.\n2. 욕실 문턱 단차 기준 미달로 물이 넘치는 경우 하자입니다.\n3. 욕실 거울 코팅 불량(부식), 트렌치 미시공 또는 배수 불량(물고임)은 기능상 하자입니다.`
  },
  {
    // [기존: 도장]
    keywords: ['도장', '페인트', '칠', '탄성', '베란다벽', '실외기실벽', '벗겨짐', '눈물자국'],
    title: '제9조 (도장 공사)',
    content: `[하자 판정 기준]\n도장(페인트) 부위에 발생한 갈라짐, 변색, 들뜸, 박락(벗겨짐), 부식, 탈락 등이 안전상, 기능상, 미관상 지장을 초래하는 경우 시공하자로 봅니다.`
  }
];

export const getMatchingStandard = (text: string) => {
  if (!text) return undefined;

  // Normalize text matching
  const target = text.trim();

  // 점수 기반 매칭 시스템
  const candidates = LEGAL_STANDARDS.map(std => {
    let score = 0;

    // 주요 카테고리 명사 (가중치 높음)
    const primaryKeywords = [
        '타일', '도배', '벽지', '마루', '창호', '샷시', '가구', '싱크대', 
        '콘크리트', '균열', '욕실', '변기', '세면대', '방화문', '현관문', 
        '단열', '석고보드', '코킹', '실리콘', '실란트', '누수', '외벽'
    ];

    std.keywords.forEach(keyword => {
       if (target.includes(keyword)) {
         // 1. 기본 점수 부여
         score += 1;

         // 2. 중요 명사가 포함된 경우 가중치 대폭 부여 (+10점)
         if (primaryKeywords.includes(keyword)) {
            score += 10;
         }
       }
    });
    return { ...std, score };
  });

  // 점수가 높은 순으로 정렬
  const matches = candidates.filter(c => c.score > 0);
  matches.sort((a, b) => b.score - a.score);

  return matches.length > 0 ? matches[0] : undefined;
};

// Helper to chunk array for photo rows
const chunk = <T>(arr: T[], size: number): T[][] => {
  return Array.from({ length: Math.ceil(arr.length / size) }, (v, i) =>
    arr.slice(i * size, i * size + size)
  );
};

// Helper to get URL string from PhotoItem
const getSrc = (item: PhotoItem): string => {
  if (typeof item === 'string') return item;
  return item.url;
};

