                    <div style="font-size: 11px; font-weight: 800; color: #94a3b8; margin-bottom: 6px;">연락처</div>
                    <div style="font-size: 18px; font-weight: 800; color: #0f172a;">${info.phoneNumber}</div>
                 </td>
                 <td style="width: 40%; padding-left: 20px; border-left: 1px solid #f1f5f9; vertical-align: middle;">
                    <div style="background: #f0f9ff; padding: 12px 16px; border-radius: 8px; border: 1px solid #e0f2fe;">
                        <table style="width: 100%; border-collapse: collapse;">
                           <tr>
                              <td style="font-size: 11px; font-weight: 700; color: #0369a1; vertical-align: middle;">총 하자 적출</td>
                              <td style="text-align: right; font-size: 20px; font-weight: 900; color: #172447; vertical-align: middle;">${defects.length}<span style="font-size:12px; font-weight:600; margin-left:2px; color:#64748b;">건</span></td>
                           </tr>
                        </table>
                    </div>
                 </td>
              </tr>
           </table>
        </div>
      </div>
    `;
    await captureAndAdd(headerHtml);

    // 2. DEFECTS PROCESSING
    const grouped = defects.reduce((acc, d) => {
      (acc[d.location] = acc[d.location] || []).push(d);
      return acc;
    }, {} as Record<string, DefectItem[]>);

    const sortedLocations = Object.keys(grouped);

    for (const location of sortedLocations) {
      const defectsInLocation = grouped[location];

      for (let i = 0; i < defectsInLocation.length; i++) {
        const d = defectsInLocation[i];
        const standard = getMatchingStandard(d.description);

        // --- ATOMIC RENDERING STRATEGY ---
        const parts: string[] = [];

        // CRITICAL: If this is the FIRST defect of the location, PREPEND the Location Header
        if (i === 0) {
            parts.push(getLocationHeaderHtml(location, defectsInLocation.length));
        }

        parts.push(getDefectHeaderHtml(i, d.description));
        if (d.farPhotos.length > 0) parts.push(getPhotoSectionHtml('원거리 (위치)', '#15803d', d.farPhotos));
        if (d.nearPhotos.length > 0) parts.push(getPhotoSectionHtml('근거리 (상세)', '#0369a1', d.nearPhotos));
        if (standard) parts.push(getStandardHtml(standard));
        parts.push(getDividerHtml());

        const fullDefectHtml = parts.join('');

        // 1. Render to an image in memory to check its height
        const { imgData, imgHeight } = await renderToImageData(fullDefectHtml);

        // 2. Decision Logic
        if (imgHeight < pageHeight) {
          // Case A: The whole defect block fits on a single page
          // Check if it fits in the *current* remaining space.
          if (cursorY + imgHeight > pageHeight) {
            pdf.addPage();
            cursorY = 0;
          }
          pdf.addImage(imgData, 'JPEG', 0, cursorY, pageWidth, imgHeight);
          cursorY += imgHeight;

        } else {
          // Case B: The defect is HUGE (too many photos). It exceeds A4 height on its own.
          // We MUST split it component by component.
          // Start on a new page to give it maximum initial space.
          if (cursorY > 20) { 
             pdf.addPage();
             cursorY = 0;
          }

          for (const partHtml of parts) {
            await captureAndAdd(partHtml);
          }
        }
      }
    }

    if (document.body.contains(container)) document.body.removeChild(container);
    return pdf.output('blob');
  } catch (err) {
    if (document.body.contains(container)) document.body.removeChild(container);
    throw err;
  }
};

export const generatePDF = async (info: InspectionInfo, defects: DefectItem[]) => {
  const blob = await generatePDFBlob(info, defects);
  const url = URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.href = url;
  link.download = `${info.apartmentName}_${info.unit}_보고서.pdf`;
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
  setTimeout(() => URL.revokeObjectURL(url), 100);
};

import React, { useState, useRef, useEffect } from 'react';
import { motion, AnimatePresence, PanInfo } from 'framer-motion';
import { X, ChevronLeft, ChevronRight, ZoomIn, ZoomOut } from 'lucide-react';

interface PhotoViewerProps {
  photos: string[];
  initialIndex: number;
  onClose: () => void;
}

const PhotoViewer: React.FC<PhotoViewerProps> = ({ photos, initialIndex, onClose }) => {
  const [index, setIndex] = useState(initialIndex);
  const [direction, setDirection] = useState(0);
  const [scale, setScale] = useState(1);

  // Reset scale when slide changes
  useEffect(() => {
    setScale(1);
  }, [index]);

  // Handle keyboard navigation
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape') onClose();
      if (e.key === 'ArrowLeft') paginate(-1);
      if (e.key === 'ArrowRight') paginate(1);
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [index]);

  const paginate = (newDirection: number) => {
    if (scale > 1) {
        setScale(1);
        // Wait for zoom out animation to finish slightly before sliding
        setTimeout(() => {
            const newIndex = index + newDirection;
            if (newIndex >= 0 && newIndex < photos.length) {
                setDirection(newDirection);
                setIndex(newIndex);
            }
        }, 250); // Adjusted timing for spring animation
    } else {
        const newIndex = index + newDirection;
        if (newIndex >= 0 && newIndex < photos.length) {
          setDirection(newDirection);
          setIndex(newIndex);
        }
    }
  };

  const toggleZoom = () => {
    setScale(prev => (prev === 1 ? 2.5 : 1));
  };

  const variants = {
    enter: (direction: number) => ({
      x: direction > 0 ? 500 : -500,
      opacity: 0,
      scale: 0.8
    }),
    center: {
      zIndex: 1,
      x: 0,
      opacity: 1,
      scale: 1
    },
    exit: (direction: number) => ({
      zIndex: 0,
      x: direction < 0 ? 500 : -500,
      opacity: 0,
      scale: 0.8
    })
  };

  const swipeConfidenceThreshold = 10000;
  const swipePower = (offset: number, velocity: number) => {
    return Math.abs(offset) * velocity;
  };

  const handleDragEnd = (e: any, { offset, velocity }: PanInfo) => {
    // Only allow swipe navigation if not zoomed in
    if (scale === 1) {
      const swipe = swipePower(offset.x, velocity.x);

      if (swipe < -swipeConfidenceThreshold) {
        paginate(1);
      } else if (swipe > swipeConfidenceThreshold) {
        paginate(-1);
      }
    }
  };

  return (
    <motion.div 
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      exit={{ opacity: 0 }}
      className="fixed inset-0 z-[100] bg-black/95 flex flex-col items-center justify-center touch-none"
    >
      {/* Header controls */}
      <div className="absolute top-0 left-0 right-0 p-4 z-20 flex justify-between items-center text-white pb-safe pt-safe-top">
        <div className="text-sm font-medium tracking-wider">
          {index + 1} / {photos.length}
        </div>
        <div className="flex gap-4">
           <button 
            onClick={toggleZoom}
            className="p-2 bg-white/10 rounded-full hover:bg-white/20 transition backdrop-blur-md"
           >
             {scale === 1 ? <ZoomIn size={20} /> : <ZoomOut size={20} />}
           </button>
           <button 
            onClick={onClose}
            className="p-2 bg-white/10 rounded-full hover:bg-white/20 transition backdrop-blur-md"
           >
            <X size={20} />
          </button>
        </div>
      </div>

      {/* Main Image Container */}
      <div className="relative w-full h-full flex items-center justify-center overflow-hidden">
        <AnimatePresence initial={false} custom={direction}>
          <motion.img
            key={index}
            src={photos[index]}
            custom={direction}
            variants={variants}
            initial="enter"
            animate="center"
            exit="exit"
            transition={{
              x: { type: "spring", stiffness: 300, damping: 30 },
              opacity: { duration: 0.2 },
              // Changed from duration to spring for smooth zoom
              scale: { type: "spring", stiffness: 200, damping: 25 } 
            }}
            drag={scale > 1 ? true : "x"} // Pan if zoomed, swipe x if not
            dragConstraints={scale > 1 ? { left: -500, right: 500, top: -500, bottom: 500 } : { left: 0, right: 0 }}
            dragElastic={scale > 1 ? 0.1 : 1}
            onDragEnd={handleDragEnd}
            onClick={(e) => e.stopPropagation()}
            onDoubleClick={toggleZoom}
            className="absolute max-h-[85vh] max-w-[95vw] object-contain shadow-2xl cursor-grab active:cursor-grabbing"
            style={{ 
                scale: scale, // Control scale via state/motion
                touchAction: 'none' // Crucial for preventing browser gestures
            }} 
          />
        </AnimatePresence>

        {/* Navigation Buttons (Desktop/Tablet) */}
        {index > 0 && (
          <button 
            className="absolute left-4 p-3 bg-white/10 rounded-full text-white hover:bg-white/20 transition hidden md:block z-10"
            onClick={(e) => { e.stopPropagation(); paginate(-1); }}
          >
            <ChevronLeft size={24} />
          </button>
        )}
        {index < photos.length - 1 && (
          <button 
            className="absolute right-4 p-3 bg-white/10 rounded-full text-white hover:bg-white/20 transition hidden md:block z-10"
            onClick={(e) => { e.stopPropagation(); paginate(1); }}
          >
            <ChevronRight size={24} />
          </button>
        )}
      </div>

      {/* Footer / Caption area if needed */}
      <div className="absolute bottom-10 flex gap-2 z-20 pb-safe">
        {photos.map((_, i) => (
          <div 
            key={i} 
            className={`w-1.5 h-1.5 rounded-full transition-all duration-300 
              ${i === index ? 'bg-white w-3' : 'bg-white/40'}`}
          />
        ))}
      </div>
    </motion.div>
  );
};

